styles.h1:
font-size: 42px;
font-weight: 700;
color: #0a0a0a;
margin-top: 20px;
margin-bottom: 30px;
text-transform: uppercase;
letter-spacing: 3px;
text-align: center;
position: relative;
padding-bottom: 20px;

styles.h2:
font-size: 32px;
font-weight: 600;
color: #d4af37;
margin-top: 30px;
margin-bottom: 20px;
text-transform: uppercase;
letter-spacing: 2px;
position: relative;
padding-left: 20px;

styles.h3:
font-size: 24px;
font-weight: 600;
color: #0a0a0a;
margin-top: 25px;
margin-bottom: 15px;
position: relative;
padding-bottom: 10px;
border-bottom: 1px solid #d4af37;

styles.h6:
color: #6b8c42;
margin-top: 1.2em;
margin-bottom: 0.5em;
font-weight: 700;
border-bottom: 1px solid #d4d9c9;
padding-bottom: 0.3em;

styles.a:
color: #d4af37;
text-decoration: none;
font-weight: 600;
position: relative;
padding: 0 2px;
transition: all 0.3s ease;

styles.ul:
background-color: rgba(212, 175, 55, 0.05);
padding: 20px;
margin: 20px 0;
position: relative;

styles.ol:
counter-reset: item;
background-color: rgba(212, 175, 55, 0.05);
padding: 20px;
margin: 20px 0;
position: relative;

styles.blockquote:
padding: 25px 25px 25px 40px;
margin: 30px 0;
color: #333;
font-style: italic;
font-weight: 400;
background-color: rgba(212, 175, 55, 0.1);
position: relative;
border-left: 2px solid #d4af37;

styles.pre:
background-color: #f8f8f8;
padding: 20px;
font-family: "SFMono-Regular", Consolas, "Liberation Mono", Menlo, monospace;
font-size: 14px;
overflow-x: auto;
color: #333;
border-left: 3px solid #d4af37;
margin: 25px 0;
position: relative;

styles.hr:
border: 0;
height: 1px;
background: linear-gradient(90deg, transparent, #d4af37, transparent);
margin: 30px 0;
position: relative;

styles.img:
max-width: 100%;
border: 1px solid #d4af37;
padding: 5px;
background-color: #fff;
position: relative;

styles.table:
border-collapse: separate;
border-spacing: 0;
width: 100%;
margin: 30px 0;
background-color: rgba(255, 255, 255, 0.8);
overflow: hidden;
position: relative;
border: 1px solid #d4af37;

styles.th:
background-color: rgba(212, 175, 55, 0.15);
color: #d4af37;
padding: 15px;
text-align: left;
font-weight: 600;
text-transform: uppercase;
letter-spacing: 1px;
border-bottom: 1px solid #d4af37;

